// Real LangGraph.js state: Annotation channels with reducers
import { Annotation } from "@langchain/langgraph";
const State = Annotation.Root({
  ticket: Annotation(),                       // overwrite (default)
  messages: Annotation({                        // append stream
    reducer: (a, b) => a.concat(b),
    default: () => [],
  }),
  decision: Annotation(),                     // single-writer slot
  attempts: Annotation({
    reducer: (a, b) => a + b,                 // counter merge
    default: () => 0,
  }),
});
// Node updates are partials: { messages: [m] } appends; { decision } overwrites.

// Reducer lab: overwrite vs append vs counter (runs in playground logic)
function applyUpdate(state, update, reducers) {
  const next = { ...state };
  for (const [k, v] of Object.entries(update)) {
    const reduce = reducers[k] || ((a, b) => b); // default: overwrite
    next[k] = k in next ? reduce(next[k], v) : v;
  }
  return next;
}
const reducers = { messages: (a, b) => a.concat(b), attempts: (a, b) => a + b };
let s = { messages: ["hi"], attempts: 1, decision: null };
s = applyUpdate(s, { messages: ["update"], attempts: 1, decision: { ok: true } }, reducers);
// messages: ["hi","update"], attempts: 2, decision: {ok:true} — each merged by rule

